 if (users.count(rnti)) {
 if (rnti != SRSRAN_MRNTI) {
 ret = users[rnti].rlc->read_pdu(lcid, payload, nof_bytes);
 } else {
 ret = users[rnti].rlc->read_pdu_mch(lcid, payload, nof_bytes);
 }
 } else {
 ret = SRSRAN_ERROR;
 }
 pthread_rwlock_unlock(&rwlock);
 return ret;
}

