 users[rnti].gtpu_itf.rnti = rnti;
 users[rnti].rrc_itf.rnti = rnti;

 users[rnti].rrc_itf.rrc = rrc;
 users[rnti].rlc_itf.rlc = rlc;
 users[rnti].gtpu_itf.gtpu = gtpu;
 users[rnti].pdcp = std::move(obj);
 }
