 return SRSRAN_ERROR;
 }
 }
 } else {
 fprintf(stderr, "Number of ARFCN in explicit_list_of_arfcns exceeds maximum (%d)\n", 31);
 return SRSRAN_ERROR;
 }
 } else {
 exp_l.resize(0);
 }
 }
 return 0;
}

